  1	import { v4 as uuidv4 } from 'uuid';
  2	import { QAResponse, QAHistory, Citation, ConversationExchange } from '../shared/types';
  3	import { PersistenceService } from './persistence-service';
  4	import { IndexingService } from './indexing-service';
  5	import { logger } from './logger';
  6	
  7	const QA_HISTORY_FILE = 'qa-history.json';
  8	
  9	/** Mock Q&A patterns keyed to document content keywords. */
 10	const MOCK_PATTERNS: Array<{
 11	  keywords: string[];
 12	  answer: string;
 13	  excerpt: string;
 14	}> = [
 15	  {
 16	    keywords: ['design', 'architecture', 'pattern'],
 17	    answer: 'The system uses a layered architecture with clear boundaries between the main process, preload scripts, and renderer. Each layer communicates through typed IPC channels, and the services layer handles business logic independently of the UI.',
 18	    excerpt: 'The system uses a layered architecture with clear boundaries',
 19	  },
 20	  {
 21	    keywords: ['import', 'document', 'file'],
 22	    answer: 'Documents are imported by copying the source file to the local data directory. The system extracts text content and creates metadata including title, filename, size, and import timestamp. After import, documents can be indexed for search.',
 23	    excerpt: 'Documents are imported by copying the source file',
 24	  },
 25	  {
 26	    keywords: ['index', 'chunk', 'search'],
 27	    answer: 'The indexing pipeline splits documents into chunks of approximately 500 characters at paragraph boundaries. Each chunk includes metadata like character count and word count. The index enables grounded Q&A with citations pointing to specific document sections.',
 28	    excerpt: 'The indexing pipeline splits documents into chunks',
 29	  },
 30	  {
 31	    keywords: ['retrieval', 'search', 'query'],
 32	    answer: 'Retrieval works by matching query keywords against indexed chunks. The system ranks chunks by keyword overlap and returns the most relevant excerpts as citations alongside the generated answer.',
 33	    excerpt: 'Retrieval works by matching query keywords against indexed chunks',
 34	  },
 35	  {
 36	    keywords: ['meeting', 'notes', 'summary'],
 37	    answer: 'The meeting summary indicates that the team discussed implementing a retrieval-augmented generation pipeline. Key decisions included using local chunk storage and citation-based verification to ensure answer accuracy.',
 38	    excerpt: 'The team discussed implementing a retrieval-augmented generation pipeline',
 39	  },
 40	];
 41	
 42	const EXCERPT_CHARS = 200;
 43	
 44	/** Shorten chunk text to an excerpt that ends on a word boundary and is marked when cut. */
 45	export function toExcerpt(content: string, max = EXCERPT_CHARS): string {
 46	  if (content.length <= max) return content;
 47	  const cut = content.slice(0, max);
 48	  const lastSpace = cut.search(/\s\S*$/);
 49	  return `${(lastSpace > max / 2 ? cut.slice(0, lastSpace) : cut).trimEnd()}…`;
 50	}
 51	
 52	export class QaService {
 53	  private persistence: PersistenceService;
 54	  private indexingService: IndexingService;
 55	  private log = logger.forService('QaService');
 56	
 57	  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
 58	    this.persistence = persistence;
 59	    this.indexingService = indexingService ?? new IndexingService(persistence);
 60	    this.log.info('QaService initialized');
 61	  }
 62	
 63	  /**
 64	   * Ask a question and get a grounded answer with citations.
 65	   *
 66	   * When `followUpOf` names an earlier exchange, that exchange's question is
 67	   * added to the retrieval context so short follow-ups ("what about chunks?")
 68	   * are answered in the context of the conversation.
 69	   */
 70	  async ask(question: string, followUpOf?: string): Promise<QAResponse> {
 71	    question = typeof question === 'string' ? question.trim() : '';
 72	    if (!question) {
 73	      throw new Error('Question must be a non-empty string');
 74	    }
 75	    const askedAt = new Date().toISOString();
 76	    const parent = followUpOf ? this.getConversation().find(e => e.id === followUpOf) : undefined;
 77	    if (followUpOf && !parent) {
 78	      this.log.warn('Follow-up target not found, answering standalone', { followUpOf });
 79	    }
 80	    const context = parent ? `${parent.question} ${question}` : question;
 81	    this.log.info('Processing question', { question, followUpOf: parent?.id ?? null });
 82	
 83	    // Simulate processing delay
 84	    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 400));
 85	
 86	    const chunks = this.indexingService.getAllChunks();
 87	    const citations: Citation[] = [];
 88	
 89	    this.log.info('Retrieving from chunks', { totalChunks: chunks.length });
 90	
 91	    if (chunks.length > 0) {
 92	      // Find relevant chunks using keyword matching
 93	      const questionWords = context.toLowerCase().split(/\s+/).filter(w => w.length > 2);
 94	      const scored = chunks.map(chunk => {
 95	        const contentLower = chunk.content.toLowerCase();
 96	        const score = questionWords.reduce(
 97	          (acc, word) => acc + (contentLower.includes(word) ? 1 : 0),
 98	          0
 99	        );
100	        return { chunk, score };
101	      });
102	
103	      // Take top 2 relevant chunks as citations
104	      const relevant = scored
105	        .filter(s => s.score > 0)
106	        .sort((a, b) => b.score - a.score)
107	        .slice(0, 2);
108	
109	      this.log.info('Keyword matching results', {
110	        questionWords: questionWords.length,
111	        relevantChunks: relevant.length,
112	      });
113	
114	      // Get document metadata for citations
115	      const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];
116	
117	      for (const { chunk } of relevant) {
118	        const doc = docs.find(d => d.id === chunk.documentId);
119	        citations.push({
120	          documentId: chunk.documentId,
121	          documentTitle: doc?.title ?? 'Unknown Document',
122	          chunkIndex: chunk.index,
123	          excerpt: toExcerpt(chunk.content),
124	        });
125	      }
126	    }
127	
128	    // Generate answer from mock patterns or use fallback
129	    const answer = this.generateAnswer(context, citations);
130	
131	    const response: QAResponse = {
132	      answer,
133	      citations,
134	      confidence: citations.length > 0 ? 0.85 : 0.3,
135	      timestamp: new Date().toISOString(),
136	    };
137	
138	    this.log.info('Q&A response generated', {
139	      confidence: response.confidence,
140	      citationCount: citations.length,
141	      answerLength: answer.length,
142	    });
143	
144	    // Save to history
145	    this.saveToHistory({ id: uuidv4(), question, askedAt, followUpOf: parent?.id, response });
146	
147	    return response;
148	  }
149	
150	  /** Get the Q&A history. */
151	  getHistory(): QAHistory[] {
152	    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
153	  }
154	
155	  /**
156	   * Get the history as a conversation, oldest exchange first. Entries saved
157	   * before conversation support get a stable index-based id and fall back to
158	   * the response timestamp for `askedAt`.
159	   */
160	  getConversation(): ConversationExchange[] {
161	    return this.getHistory().map((entry, index) => ({
162	      id: entry.id ?? `legacy-${index}`,
163	      question: entry.question,
164	      askedAt: entry.askedAt ?? entry.response.timestamp,
165	      followUpOf: entry.followUpOf ?? null,
166	      response: entry.response,
167	    }));
168	  }
169	
170	  /** Clear the Q&A history. */
171	  clearHistory(): void {
172	    this.persistence.writeJson(QA_HISTORY_FILE, []);
173	    this.log.info('Q&A history cleared');
174	  }
175	
176	  private generateAnswer(question: string, citations: Citation[]): string {
177	    // Match against mock patterns
178	    const questionLower = question.toLowerCase();
179	    for (const pattern of MOCK_PATTERNS) {
180	      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
181	        if (citations.length > 0) {
182	          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
183	        }
184	        return pattern.answer;
185	      }
186	    }
187	
188	    // Fallback answer
189	    if (citations.length > 0) {
190	      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
191	    }
192	
193	    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
194	  }
195	
196	  private saveToHistory(entry: QAHistory): void {
197	    const history = this.getHistory();
198	    history.push(entry);
199	    this.persistence.writeJson(QA_HISTORY_FILE, history);
200	    this.log.info('Question saved to history', { historyLength: history.length });
201	  }
202	}
  1	import * as fs from 'fs';
  2	import * as path from 'path';
  3	
  4	export class PersistenceService {
  5	  private dataDir: string;
  6	  private documentsDir: string;
  7	  private indexDir: string;
  8	
  9	  constructor(dataDir: string) {
 10	    this.dataDir = dataDir;
 11	    this.documentsDir = path.join(dataDir, 'documents');
 12	    this.indexDir = path.join(dataDir, 'index');
 13	    this.ensureDirectories();
 14	  }
 15	
 16	  private ensureDirectories() {
 17	    fs.mkdirSync(this.dataDir, { recursive: true });
 18	    fs.mkdirSync(this.documentsDir, { recursive: true });
 19	    fs.mkdirSync(this.indexDir, { recursive: true });
 20	  }
 21	
 22	  /** Read a JSON file, returning null if it doesn't exist. */
 23	  readJson<T>(relativePath: string): T | null {
 24	    const fullPath = path.join(this.dataDir, relativePath);
 25	    if (!fs.existsSync(fullPath)) return null;
 26	    return JSON.parse(fs.readFileSync(fullPath, 'utf-8'));
 27	  }
 28	
 29	  /** Write a JSON file atomically. */
 30	  writeJson<T>(relativePath: string, data: T): void {
 31	    const fullPath = path.join(this.dataDir, relativePath);
 32	    const dir = path.dirname(fullPath);
 33	    fs.mkdirSync(dir, { recursive: true });
 34	    fs.writeFileSync(fullPath, JSON.stringify(data, null, 2), 'utf-8');
 35	  }
 36	
 37	  /** Read a text file. */
 38	  readText(relativePath: string): string | null {
 39	    const fullPath = path.join(this.dataDir, relativePath);
 40	    if (!fs.existsSync(fullPath)) return null;
 41	    return fs.readFileSync(fullPath, 'utf-8');
 42	  }
 43	
 44	  /** Write a text file. */
 45	  writeText(relativePath: string, content: string): void {
 46	    const fullPath = path.join(this.dataDir, relativePath);
 47	    const dir = path.dirname(fullPath);
 48	    fs.mkdirSync(dir, { recursive: true });
 49	    fs.writeFileSync(fullPath, content, 'utf-8');
 50	  }
 51	
 52	  /** Copy a file into the documents directory. */
 53	  copyFileToDocuments(sourcePath: string, filename: string): string {
 54	    const destPath = path.join(this.documentsDir, filename);
 55	    fs.mkdirSync(this.documentsDir, { recursive: true });
 56	    fs.copyFileSync(sourcePath, destPath);
 57	    return destPath;
 58	  }
 59	
 60	  /** Delete a file from the documents directory. */
 61	  deleteFromDocuments(filename: string): void {
 62	    const filePath = path.join(this.documentsDir, filename);
 63	    if (fs.existsSync(filePath)) {
 64	      fs.unlinkSync(filePath);
 65	    }
 66	  }
 67	
 68	  /** List all files in a directory. */
 69	  listFiles(relativePath: string): string[] {
 70	    const fullPath = path.join(this.dataDir, relativePath);
 71	    if (!fs.existsSync(fullPath)) return [];
 72	    return fs.readdirSync(fullPath);
 73	  }
 74	
 75	  /** Check if a file exists. */
 76	  exists(relativePath: string): boolean {
 77	    return fs.existsSync(path.join(this.dataDir, relativePath));
 78	  }
 79	
 80	  /** Get the data directory path. */
 81	  getDataDir(): string {
 82	    return this.dataDir;
 83	  }
 84	
 85	  /** Get the documents directory path. */
 86	  getDocumentsDir(): string {
 87	    return this.documentsDir;
 88	  }
 89	
 90	  /** Get the index directory path. */
 91	  getIndexDir(): string {
 92	    return this.indexDir;
 93	  }
 94	}
  1	/** Cross-boundary type definitions shared between main, preload, and renderer. */
  2	
  3	export interface Document {
  4	  id: string;
  5	  title: string;
  6	  filename: string;
  7	  importedAt: string;
  8	  size: number;
  9	  status: 'imported' | 'indexing' | 'indexed' | 'error';
 10	  chunks?: number;
 11	}
 12	
 13	export interface Chunk {
 14	  id: string;
 15	  documentId: string;
 16	  content: string;
 17	  index: number;
 18	  metadata: Record<string, string>;
 19	}
 20	
 21	export interface Citation {
 22	  documentId: string;
 23	  documentTitle: string;
 24	  chunkIndex: number;
 25	  excerpt: string;
 26	}
 27	
 28	export interface QAResponse {
 29	  answer: string;
 30	  citations: Citation[];
 31	  confidence: number;
 32	  timestamp: string;
 33	}
 34	
 35	/**
 36	 * One persisted Q&A exchange. `id`, `askedAt` and `followUpOf` are optional
 37	 * because history files written before conversation support lack them.
 38	 */
 39	export interface QAHistory {
 40	  id?: string;
 41	  question: string;
 42	  askedAt?: string;
 43	  followUpOf?: string;
 44	  response: QAResponse;
 45	}
 46	
 47	/** A normalized exchange in the multi-turn conversation, oldest first. */
 48	export interface ConversationExchange {
 49	  id: string;
 50	  question: string;
 51	  /** ISO timestamp of when the question was asked. */
 52	  askedAt: string;
 53	  /** Id of the earlier exchange this question follows up on, if any. */
 54	  followUpOf: string | null;
 55	  response: QAResponse;
 56	}
 57	
 58	export interface AppStatus {
 59	  documentsLoaded: number;
 60	  indexStatus: 'idle' | 'indexing' | 'ready' | 'error';
 61	  lastActivity: string;
 62	}
 63	
 64	/** IPC channel names — single source of truth. */
 65	export const IPC_CHANNELS = {
 66	  // Document operations
 67	  LIST_DOCUMENTS: 'documents:list',
 68	  IMPORT_DOCUMENT: 'documents:import',
 69	  GET_DOCUMENT: 'documents:get',
 70	  DELETE_DOCUMENT: 'documents:delete',
 71	
 72	  // Indexing
 73	  START_INDEXING: 'indexing:start',
 74	  GET_INDEXING_STATUS: 'indexing:status',
 75	  GET_CHUNKS: 'indexing:chunks',
 76	
 77	  // Q&A
 78	  ASK_QUESTION: 'qa:ask',
 79	  GET_HISTORY: 'qa:history',
 80	  CLEAR_HISTORY: 'qa:clear-history',
 81	
 82	  // Conversation
 83	  GET_CONVERSATION: 'conversation:get',
 84	
 85	  // App status
 86	  GET_STATUS: 'app:status',
 87	} as const;
  1	import { contextBridge, ipcRenderer } from 'electron';
  2	import { IPC_CHANNELS } from '../shared/types';
  3	
  4	const api = {
  5	  documents: {
  6	    list: () => ipcRenderer.invoke(IPC_CHANNELS.LIST_DOCUMENTS),
  7	    import: (filePath: string) => ipcRenderer.invoke(IPC_CHANNELS.IMPORT_DOCUMENT, filePath),
  8	    get: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.GET_DOCUMENT, id),
  9	    delete: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.DELETE_DOCUMENT, id),
 10	  },
 11	  indexing: {
 12	    start: (documentId?: string) => ipcRenderer.invoke(IPC_CHANNELS.START_INDEXING, documentId),
 13	    status: () => ipcRenderer.invoke(IPC_CHANNELS.GET_INDEXING_STATUS),
 14	    chunks: (documentId: string) => ipcRenderer.invoke(IPC_CHANNELS.GET_CHUNKS, documentId),
 15	  },
 16	  qa: {
 17	    ask: (question: string, followUpOf?: string) =>
 18	      ipcRenderer.invoke(IPC_CHANNELS.ASK_QUESTION, question, followUpOf),
 19	    history: () => ipcRenderer.invoke(IPC_CHANNELS.GET_HISTORY),
 20	    clearHistory: () => ipcRenderer.invoke(IPC_CHANNELS.CLEAR_HISTORY),
 21	  },
 22	  conversation: {
 23	    get: () => ipcRenderer.invoke(IPC_CHANNELS.GET_CONVERSATION),
 24	  },
 25	};
 26	
 27	contextBridge.exposeInMainWorld('knowledgeBase', api);
  1	/// <reference types="react" />
  2	/// <reference types="react-dom" />
  3	
  4	declare global {
  5	  interface Window {
  6	    knowledgeBase: {
  7	      documents: {
  8	        list: () => Promise<import('../shared/types').Document[]>;
  9	        import: (filePath: string) => Promise<import('../shared/types').Document>;
 10	        get: (id: string) => Promise<import('../shared/types').Document | null>;
 11	        delete: (id: string) => Promise<boolean>;
 12	      };
 13	      indexing: {
 14	        start: (documentId?: string) => Promise<import('../shared/types').AppStatus>;
 15	        status: () => Promise<import('../shared/types').AppStatus>;
 16	        chunks: (documentId: string) => Promise<import('../shared/types').Chunk[]>;
 17	      };
 18	      qa: {
 19	        ask: (question: string, followUpOf?: string) => Promise<import('../shared/types').QAResponse>;
 20	        history: () => Promise<import('../shared/types').QAHistory[]>;
 21	        clearHistory: () => Promise<void>;
 22	      };
 23	      conversation: {
 24	        get: () => Promise<import('../shared/types').ConversationExchange[]>;
 25	      };
 26	    };
 27	  }
 28	}
