  1	import { IpcMain } from 'electron';
  2	import { DocumentService } from '../services/document-service';
  3	import { IndexingService } from '../services/indexing-service';
  4	import { QaService } from '../services/qa-service';
  5	import { IPC_CHANNELS } from '../shared/types';
  6	import { logger } from '../services/logger';
  7	
  8	export interface Services {
  9	  documentService: DocumentService;
 10	  indexingService: IndexingService;
 11	  qaService: QaService;
 12	}
 13	
 14	export function registerIpcHandlers(ipcMain: IpcMain, services: Services) {
 15	  const { documentService, indexingService, qaService } = services;
 16	  const log = logger.forService('IPC');
 17	
 18	  // Document operations
 19	  ipcMain.handle(IPC_CHANNELS.LIST_DOCUMENTS, async () => {
 20	    log.info('LIST_DOCUMENTS');
 21	    return documentService.listDocuments();
 22	  });
 23	
 24	  ipcMain.handle(IPC_CHANNELS.IMPORT_DOCUMENT, async (_event, filePath: string) => {
 25	    log.info('IMPORT_DOCUMENT', { filePath });
 26	    try {
 27	      const doc = documentService.importDocument(filePath);
 28	      log.info('Document imported', { id: doc.id, title: doc.title, size: doc.size });
 29	      return doc;
 30	    } catch (err) {
 31	      log.error('Document import failed', { filePath, error: String(err) });
 32	      throw err;
 33	    }
 34	  });
 35	
 36	  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT, async (_event, id: string) => {
 37	    log.info('GET_DOCUMENT', { id });
 38	    return documentService.getDocument(id);
 39	  });
 40	
 41	  ipcMain.handle(IPC_CHANNELS.DELETE_DOCUMENT, async (_event, id: string) => {
 42	    log.info('DELETE_DOCUMENT', { id });
 43	    return documentService.deleteDocument(id);
 44	  });
 45	
 46	  // Indexing
 47	  ipcMain.handle(IPC_CHANNELS.START_INDEXING, async (_event, documentId?: string) => {
 48	    log.info('START_INDEXING', { documentId: documentId ?? 'all' });
 49	    try {
 50	      const status = await indexingService.startIndexing(documentId);
 51	      log.info('Indexing complete', { status: status.status, indexed: status.currentIndexed, total: status.totalDocuments });
 52	      return status;
 53	    } catch (err) {
 54	      log.error('Indexing failed', { documentId, error: String(err) });
 55	      throw err;
 56	    }
 57	  });
 58	
 59	  ipcMain.handle(IPC_CHANNELS.GET_INDEXING_STATUS, async () => {
 60	    return indexingService.getStatus();
 61	  });
 62	
 63	  ipcMain.handle(IPC_CHANNELS.GET_CHUNKS, async (_event, documentId: string) => {
 64	    log.info('GET_CHUNKS', { documentId });
 65	    return indexingService.getChunksForDocument(documentId);
 66	  });
 67	
 68	  // Q&A
 69	  ipcMain.handle(IPC_CHANNELS.ASK_QUESTION, async (_event, question: string, followUpOf?: string) => {
 70	    log.info('ASK_QUESTION', { question, followUpOf: followUpOf ?? null });
 71	    try {
 72	      const response = await qaService.ask(question, followUpOf);
 73	      log.info('Q&A response', {
 74	        confidence: response.confidence,
 75	        citationCount: response.citations.length,
 76	      });
 77	      return response;
 78	    } catch (err) {
 79	      log.error('Q&A failed', { question, error: String(err) });
 80	      throw err;
 81	    }
 82	  });
 83	
 84	  ipcMain.handle(IPC_CHANNELS.GET_HISTORY, async () => {
 85	    log.info('GET_HISTORY');
 86	    return qaService.getHistory();
 87	  });
 88	
 89	  ipcMain.handle(IPC_CHANNELS.CLEAR_HISTORY, async () => {
 90	    log.info('CLEAR_HISTORY');
 91	    qaService.clearHistory();
 92	  });
 93	
 94	  // Conversation
 95	  ipcMain.handle(IPC_CHANNELS.GET_CONVERSATION, async () => {
 96	    const conversation = qaService.getConversation();
 97	    log.info('GET_CONVERSATION', { exchanges: conversation.length });
 98	    return conversation;
 99	  });
100	}

