  1	import { useEffect, useRef, useState, type CSSProperties } from 'react';
  2	import { Citation, ConversationExchange } from '../../shared/types';
  3	import { formatFullTimestamp, formatTimestamp } from '../format';
  4	
  5	/** Answers longer than this start collapsed behind a "Show full answer" toggle. */
  6	const LONG_ANSWER_CHARS = 1200;
  7	
  8	export const bubbleBase: CSSProperties = {
