 38	interface Props {
 39	  exchange: ConversationExchange;
 40	  /** The exchange this one follows up on, when it is still in the history. */
 41	  parent: ConversationExchange | null;
 42	  highlighted: boolean;
 43	  isDocumentAvailable: (documentId: string) => boolean;
 44	  onOpenDocument: (documentId: string) => void;
 45	  onFollowUp: (exchange: ConversationExchange) => void;
 46	  onJumpTo: (exchangeId: string) => void;
 47	}
 48	
 49	export function ExchangeItem({
 50	  exchange,
 51	  parent,
 52	  highlighted,
 53	  isDocumentAvailable,
 54	  onOpenDocument,
 55	  onFollowUp,
 56	  onJumpTo,
 57	}: Props) {
 58	  const { response } = exchange;
 59	  const isLong = response.answer.length > LONG_ANSWER_CHARS;
 60	  const [expanded, setExpanded] = useState(false);
 61	  const [showSources, setShowSources] = useState(true);
 62	  const [copyStatus, setCopyStatus] = useState('');
 63	  const copyTimer = useRef<number | undefined>(undefined);
 64	  const answerId = `answer-${exchange.id}`;
 65	  const sourcesId = `sources-${exchange.id}`;
 66	  const confidencePct = Math.round(response.confidence * 100);
 67	  const lowConfidence = response.confidence < 0.5;
 68	
 69	  useEffect(() => () => window.clearTimeout(copyTimer.current), []);
 70	
 71	  const copyAnswer = async () => {
 72	    try {
 73	      await navigator.clipboard.writeText(response.answer);
 74	      setCopyStatus('Copied');
 75	    } catch {
 76	      setCopyStatus('Copy failed');
 77	    }
 78	    window.clearTimeout(copyTimer.current);
 79	    copyTimer.current = window.setTimeout(() => setCopyStatus(''), 2000);
 80	  };
 81	
 82	  return (
 83	    <article
 84	      id={`exchange-${exchange.id}`}
 85	      tabIndex={-1}
 86	      aria-labelledby={`question-${exchange.id}`}
 87	      style={{
 88	        display: 'flex',
 89	        flexDirection: 'column',
 90	        gap: '8px',
 91	        padding: '8px',
 92	        borderRadius: '8px',
 93	        outlineOffset: '2px',
 94	        background: highlighted ? 'rgba(83, 52, 131, 0.18)' : 'transparent',
 95	        transition: 'background 0.3s',
 96	      }}
 97	    >
 98	      {/* User question */}
 99	      <div style={{ alignSelf: 'flex-end', display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '4px', maxWidth: '80%' }}>
100	        <div style={metaText}>
101	          <span style={{ fontWeight: 600, color: '#c9b6ef' }}>You</span>
102	          {' · '}
103	          <time dateTime={exchange.askedAt} title={formatFullTimestamp(exchange.askedAt)}>
104	            {formatTimestamp(exchange.askedAt)}
105	          </time>
106	        </div>
107	        {exchange.followUpOf && (
108	          <div style={metaText}>
109	            {parent ? (
110	              <button
111	                type="button"
112	                onClick={() => onJumpTo(parent.id)}
113	                style={{ ...smallButton, border: 'none', padding: 0, color: '#9a9ac0', textDecoration: 'underline' }}
114	                title="Jump to the earlier question"
