116	                ↪ Follow-up to “{truncate(parent.question, 60)}”
117	              </button>
118	            ) : (
119	              <span>↪ Follow-up to an earlier question</span>
120	            )}
121	          </div>
122	        )}
123	        <h3 id={`question-${exchange.id}`} style={{ ...userBubble, maxWidth: '100%', fontWeight: 400, margin: 0 }}>
124	          {exchange.question}
125	        </h3>
126	      </div>
127	
128	      {/* Assistant answer */}
129	      <div style={{ alignSelf: 'flex-start', maxWidth: '88%', display: 'flex', flexDirection: 'column', gap: '4px' }}>
130	        <div style={metaText}>
131	          <span style={{ fontWeight: 600, color: '#8fb3ff' }}>Assistant</span>
