  1	/** Display-only formatting helpers for the renderer. */
  2	
  3	const timeFormat = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });
  4	const dateFormat = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' });
  5	const dateYearFormat = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  6	const fullFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'full', timeStyle: 'medium' });
  7	
  8	function startOfDay(date: Date): number {
  9	  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
 10	}
 11	
 12	/** Short, readable timestamp: "Today, 14:32", "Yesterday, 09:05", "Mar 3, 10:00", "Mar 3, 2025, 10:00". */
 13	export function formatTimestamp(iso: string, now: Date = new Date()): string {
 14	  const date = new Date(iso);
 15	  if (Number.isNaN(date.getTime())) return 'Unknown time';
 16	
 17	  const time = timeFormat.format(date);
 18	  const dayDiff = Math.round((startOfDay(now) - startOfDay(date)) / 86_400_000);
 19	  if (dayDiff === 0) return `Today, ${time}`;
 20	  if (dayDiff === 1) return `Yesterday, ${time}`;
 21	  if (date.getFullYear() === now.getFullYear()) return `${dateFormat.format(date)}, ${time}`;
 22	  return `${dateYearFormat.format(date)}, ${time}`;
 23	}
 24	
 25	/** Full timestamp for tooltips. */
 26	export function formatFullTimestamp(iso: string): string {
 27	  const date = new Date(iso);
 28	  return Number.isNaN(date.getTime()) ? 'Unknown time' : fullFormat.format(date);
 29	}
 30	
 31	/** Strip Electron's IPC wrapper from an error so the user sees the real reason. */
 32	export function formatIpcError(err: unknown): string {
 33	  const raw = err instanceof Error ? err.message : String(err);
 34	  return raw.replace(/^Error invoking remote method '[^']+':\s*(Error:\s*)?/, '') || 'Unknown error';
 35	}
