import { useEffect, useState } from 'react';
import { Document, Chunk } from '../../shared/types';

/** A request to reveal one chunk; `seq` lets the same chunk be requested twice. */
export interface ChunkFocus {
  documentId: string;
  /** 0-based chunk index, as stored in citations. */
  index: number;
  seq: number;
}

interface Props {
  document: Document;
  /** When set, chunks are shown and this chunk is scrolled to, focused and highlighted. */
  focus?: ChunkFocus | null;
}

const chunkElementId = (documentId: string, index: number) => `chunk-${documentId}-${index}`;

export function DocumentDetail({ document, focus = null }: Props) {
  const [loaded, setLoaded] = useState<{ documentId: string; chunks: Chunk[] } | null>(null);
  const [showChunks, setShowChunks] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    window.knowledgeBase.indexing.chunks(document.id).then(chunks => {
      if (!cancelled) setLoaded({ documentId: document.id, chunks });
    });
    return () => { cancelled = true; };
  }, [document.id]);

  const chunks = loaded?.documentId === document.id ? loaded.chunks : [];
  const chunksReady = loaded?.documentId === document.id;

  // A citation was opened: reveal the chunk list and mark the cited chunk.
  useEffect(() => {
    if (!focus) {
      setHighlightedIndex(null);
      return;
    }
    setShowChunks(true);
    setHighlightedIndex(focus.index);
  }, [focus]);

  // Once the chunk is rendered, bring it into view and move focus to it.
  useEffect(() => {
    if (!focus || !chunksReady || !showChunks) return;
    const el = window.document.getElementById(chunkElementId(document.id, focus.index));
    if (!el) return;
    el.scrollIntoView({ block: 'start' });
    el.focus({ preventScroll: true });
  }, [focus, chunksReady, showChunks, document.id]);

  const focusMissing = focus !== null && chunksReady && !chunks.some(c => c.index === focus.index);

  return (
    <div>
      <h2 style={{ fontSize: '20px', fontWeight: 600, marginBottom: '8px' }}>
        {document.title}
      </h2>
      <div style={{ fontSize: '13px', color: '#888', marginBottom: '16px' }}>
        <div>Filename: {document.filename}</div>
        <div>Imported: {new Date(document.importedAt).toLocaleString()}</div>
        <div>Size: {(document.size / 1024).toFixed(1)} KB</div>
        <div>Status: {document.status}</div>
        {document.chunks !== undefined && <div>Chunks: {document.chunks}</div>}
      </div>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        <button
          type="button"
          aria-expanded={showChunks}
          onClick={() => setShowChunks(!showChunks)}
          style={{
            padding: '6px 12px',
            background: '#0f3460',
            color: '#e0e0e0',
            border: '1px solid #1a1a4e',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '12px',
          }}
        >
          {showChunks ? 'Hide' : 'Show'} Chunks ({chunks.length})
        </button>
        {document.status !== 'indexed' && (
          <button
            type="button"
            onClick={() => window.knowledgeBase.indexing.start(document.id)}
            style={{
              padding: '6px 12px',
              background: '#533483',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '12px',
            }}
          >
            Index Document
          </button>
        )}
      </div>

      {focusMissing && (
        <p role="status" style={{ fontSize: '12px', color: '#f0ad4e', marginBottom: '8px' }}>
          The cited chunk {focus.index + 1} is no longer in this document's index (it may have been re-indexed).
        </p>
      )}

      {showChunks && (
        <div>
          {chunks.map(chunk => {
            const cited = chunk.index === highlightedIndex;
            return (
              <div
                key={chunk.id}
                id={chunkElementId(document.id, chunk.index)}
                tabIndex={-1}
                aria-current={cited ? 'true' : undefined}
                aria-label={cited ? `Chunk ${chunk.index + 1}, cited in the answer` : undefined}
                style={{
                  padding: '10px',
                  marginBottom: '8px',
                  background: cited ? 'rgba(83, 52, 131, 0.35)' : '#1a1a3e',
                  borderRadius: '4px',
                  borderLeft: cited ? '3px solid #c9b6ef' : '3px solid #533483',
                  outline: cited ? '1px solid #533483' : undefined,
                  fontSize: '13px',
                  lineHeight: 1.5,
                  whiteSpace: 'pre-wrap',
                  overflowWrap: 'anywhere',
                }}
              >
                <div style={{ fontSize: '11px', color: cited ? '#c9b6ef' : '#888', marginBottom: '4px' }}>
                  Chunk {chunk.index + 1} ({chunk.metadata.charCount} chars){cited ? ' · cited in the answer' : ''}
                </div>
                {chunk.content}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

