p='tests/qa-conversation.test.ts'
s=open(p).read()
s=s.replace("import { mkdtempSync, rmSync } from 'fs';","import { chmodSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'fs';")
s=s.replace("import { QaService, toExcerpt } from '../src/services/qa-service';","import { QaService, retrievalTerms, toExcerpt } from '../src/services/qa-service';\nimport { truncateAtWord } from '../src/shared/text';")
anchor="  it('clears the conversation', async () => {"
new='''  it('skips malformed entries instead of hiding the whole conversation, and keeps them on disk', async () => {
    const good = { id: 'ok', question: 'good', askedAt: '2026-01-02T03:04:05.000Z', response: { answer: 'fine', citations: [], confidence: 0.3, timestamp: '2026-01-02T03:04:06.000Z' } };
    persistence.writeJson('qa-history.json', [good, { question: 'no response' }, { response: { answer: 'no question' } }, null, 'junk', { question: 'bad answer', response: { answer: 42 } }]);

    const conversation = qa.getConversation();
    expect(conversation.map(e => e.id)).toEqual(['ok']);

    await qa.ask('a new question');
    const onDisk = persistence.readJson<unknown[]>('qa-history.json')!;
    expect(onDisk).toHaveLength(7); // the 6 original entries are preserved, plus the new one
    expect(qa.getConversation().map(e => e.question)).toEqual(['good', 'a new question']);
  });

  it('fills defaults for partially missing response fields', () => {
    persistence.writeJson('qa-history.json', [{ question: 'q', response: { answer: 'a', citations: [{ documentId: 'd' }, 'bad'] } }]);
    const [e] = qa.getConversation();
    expect(e.response.citations).toEqual([{ documentId: 'd', documentTitle: 'Unknown Document', chunkIndex: 0, excerpt: '' }]);
    expect(e.response.confidence).toBe(0);
  });

  it('reports a corrupt history file with a user-facing message and does not overwrite it', async () => {
    const file = join(dir, 'qa-history.json');
    writeFileSync(file, '{not json');
    expect(() => qa.getConversation()).toThrow(/conversation history file is unreadable \\(.*qa-history\\.json\\)/);
    expect(() => qa.getConversation()).not.toThrow(/SyntaxError|JSON|position/);
    await expect(qa.ask('anything')).rejects.toThrow(/unreadable/);
    expect(readFileSync(file, 'utf-8')).toBe('{not json');
  });

  it('treats a history file that is not a list as unreadable', () => {
    persistence.writeJson('qa-history.json', { not: 'a list' });
    expect(() => qa.getConversation()).toThrow(/unreadable/);
  });

  it('translates a failed save into a user-facing message', async () => {
    await qa.ask('first');
    const file = join(dir, 'qa-history.json');
    chmodSync(file, 0o444);
    try {
      await expect(qa.ask('second')).rejects.toThrow(/Could not save to the conversation history file .*permission denied/);
    } finally {
      chmodSync(file, 0o644);
    }
  });

  it('keeps the original topic across a follow-up chain longer than two turns', async () => {
    const docs = new DocumentService(persistence);
    docs.importDocument(join(SAMPLES, 'retrieval-plan.md'));
    docs.importDocument(join(SAMPLES, 'design-notes.md'));
    await new IndexingService(persistence).startIndexing();

    await qa.ask('Explain the retrieval chunk ranking');
    const [root] = qa.getConversation();
    await qa.ask('and then?', root.id);
    const second = qa.getConversation()[1];
    const third = await qa.ask('why?', second.id);
    const fourth = await qa.ask('really?', qa.getConversation()[2].id);

    // Without context these questions are only stop words and match nothing.
    expect(retrievalTerms('and then? why?')).toEqual([]);
    expect((await qa.ask('and then? why?')).citations).toHaveLength(0);
    expect(third.citations.length).toBeGreaterThan(0);
    expect(fourth.citations.length).toBeGreaterThan(0);
